<?php
require_once 'includes/config.php';require_once 'includes/functions.php';require_tourist();$page_title='My travel dashboard';
$s=$pdo->prepare("SELECT b.*,p.package_name,p.price FROM bookings b JOIN tour_packages p ON b.package_id=p.package_id WHERE b.tourist_id=? ORDER BY b.booking_id DESC");$s->execute([$_SESSION['tourist_id']]);$bookings=$s->fetchAll();
$featuredDestinations=$pdo->query("SELECT destination_name,city,country,description,image_url FROM destinations ORDER BY destination_id DESC LIMIT 3")->fetchAll();
require 'includes/header.php';?>
<div class="container dashboard-layout account-layout"><div class="account-sidebar-card"><?php require 'includes/account_sidebar.php'; ?></div><section class="dashboard-main account-content-card"><span class="eyebrow">Your TravelHub space</span><h1>Hello, <?= e($_SESSION['tourist_name']??'traveller') ?> 👋</h1><p>Keep your travel plans, booking details and next adventures in one place.</p><div class="dash-cards"><div class="dash-card"><strong><?= count($bookings) ?></strong><span>Total bookings</span></div><div class="dash-card"><strong><?= count(array_filter($bookings,fn($b)=>$b['booking_status']==='Confirmed')) ?></strong><span>Confirmed trips</span></div><div class="dash-card"><strong><?= count(array_filter($bookings,fn($b)=>$b['booking_status']==='Pending')) ?></strong><span>Pending requests</span></div></div><?php if($featuredDestinations): ?><section class="dashboard-discover"><div class="admin-head"><div><span class="eyebrow">A little inspiration</span><h2>Explore beautiful places</h2></div><a class="btn small-btn" href="destinations.php">All destinations ↗</a></div><div class="grid-3 destination-grid account-destination-grid"><?php foreach($featuredDestinations as $fd): ?><article class="destination-card"><div class="card-image"><img loading="lazy" src="<?= e(travel_image_src($fd['destination_name'], $fd['image_url'])) ?>" alt="<?= e($fd['destination_name']) ?>" onerror="this.onerror=null;this.src='assets/images/tropical-coast.jpg'"><span class="image-tag"><?= e($fd['country']) ?></span></div><div class="card-body"><h3><?= e($fd['destination_name']) ?></h3><p class="muted">⌖ <?= e($fd['city']) ?>, <?= e($fd['country']) ?></p><p><?= e($fd['description']) ?></p></div></article><?php endforeach; ?></div></section><?php endif; ?><div class="admin-head" id="bookings"><h2>My bookings</h2><a class="btn small-btn" href="bookings.php">View all bookings ↗</a></div>
<?php if(!$bookings): ?><div class="empty-state"><h3>Your travel story starts here</h3><p>You have no bookings yet. Explore packages to plan your first trip.</p><a class="btn" href="packages.php">Explore packages</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Package</th><th>Travel date</th><th>Travellers</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?= e($b['package_name']) ?><br><small class="muted">#TH<?= (int)$b['booking_id'] ?></small></td><td><?= e($b['travel_date']) ?></td><td><?= (int)$b['number_of_persons'] ?></td><td><?= money($b['total_amount']) ?></td><td><span class="status <?= $b['booking_status']==='Pending'?'pending':'' ?>"><?= e($b['booking_status']) ?></span></td><td><?php if($b['booking_status']!=='Cancelled'): ?><a class="text-link" href="payment.php?booking_id=<?= (int)$b['booking_id'] ?>">Payment ↗</a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require 'includes/footer.php'; ?>
